<?php
declare(strict_types=1);
verify_csrf();
$action=(string)($_POST['action']??'');
if($action==='add'){$id=(int)($_POST['id']??0);$prod=get_product($id);if(!$prod){flash('This item is no longer available.','warn');redirect('shop');}$quantity=max(1,min(20,(int)($_POST['qty']??1)));$_SESSION['cart'][$id]=min(20,(int)($_SESSION['cart'][$id]??0)+$quantity);flash($prod['name'].' added to your bag.');redirect('cart');}
if($action==='cart_update'){$id=(int)($_POST['id']??0);$qty=max(0,min(20,(int)($_POST['qty']??0)));if($qty===0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;redirect('cart');}
if($action==='register'){$name=input('name',100);$email=strtolower(input('email',190));$pass=(string)($_POST['password']??'');if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){flash('Enter your name, valid email and password of 8+ characters.','error');redirect('register');}try{$st=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'customer')");$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];flash('Welcome to the family!');redirect();}catch(PDOException $e){if($e->getCode()==='23000'){flash('This email already has an account.','warn');redirect('register');}throw $e;}}
if($action==='login'){$email=strtolower(input('email',190));$pass=(string)($_POST['password']??'');$st=db()->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$st->execute([$email]);$u=$st->fetch();if(!$u||!password_verify($pass,$u['password_hash'])){flash('Incorrect email or password.','error');redirect('login');}session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];flash('You are signed in.');redirect($u['role']==='admin'?'admin':'home');}
if($action==='message'){$name=input('name',100);$email=input('email',190);$body=input('message',2000);if(mb_strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($body)<10){flash('Complete all fields with a valid email and message (10+ characters).','error');redirect('contact');}$st=db()->prepare('INSERT INTO contact_messages(name,email,message) VALUES(?,?,?)');$st->execute([$name,$email,$body]);flash('Thanks! Your message was received.');redirect('contact');}
if($action==='checkout'){require_login();$name=input('name',100);$phone=input('phone',30);$address=input('address',255);$note=input('note',500);$method=input('payment_method',20);if(mb_strlen($name)<2||!preg_match('/^[+0-9() -]{8,20}$/',$phone)||mb_strlen($address)<8||!in_array($method,['cod','pickup'],true)){flash('Please check your delivery details.','error');redirect('checkout');} $selection=cart();if(!$selection){flash('Your bag is empty.','warn');redirect('shop');}$pdo=db();$pdo->beginTransaction();try{$ids=array_values(array_filter(array_map('intval',array_keys($selection)),fn($id)=>$id>0));$ph=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT id,price,stock,name FROM products WHERE active=1 AND id IN ($ph) FOR UPDATE");$st->execute($ids);$rows=$st->fetchAll();if(count($rows)!==count($ids))throw new RuntimeException('Some products are no longer available.');$subtotal=0.;foreach($rows as $row){$qty=(int)$selection[$row['id']];if($qty<1||$qty>20||$qty>(int)$row['stock'])throw new RuntimeException($row['name'].' has insufficient stock.');$subtotal+=(float)$row['price']*$qty;}$delivery=$method==='pickup'||$subtotal>=25?0:2.00;$st=$pdo->prepare("INSERT INTO orders(user_id,customer_name,phone,address,note,payment_method,subtotal,delivery_fee,total,status) VALUES(?,?,?,?,?,?,?,?,?,'pending')");$st->execute([auth()['id'],$name,$phone,$address,$note,$method,$subtotal,$delivery,$subtotal+$delivery]);$orderId=(int)$pdo->lastInsertId();$detail=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($rows as $row){$qty=(int)$selection[$row['id']];$detail->execute([$orderId,$row['id'],$qty,$row['price']]);$stock->execute([$qty,$row['id']]);}$pdo->commit();unset($_SESSION['cart']);flash('Order #'.$orderId.' was placed successfully!');redirect('orders');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Unable to complete your order. Please retry.','error');redirect('checkout');}}
if(str_starts_with($action,'admin_')){require_admin();if($action==='admin_product_save'){$id=(int)($_POST['id']??0);$name=input('name',120);$desc=input('short_description',200);$details=input('description',2000);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);$cat=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT);$image=input('image_key',30);$featured=isset($_POST['featured'])?1:0;if(mb_strlen($name)<2||$price===false||$price<0.01||$stock===false||$stock<0||!$cat||!in_array($image,['cake','croissant','cookies','bread','cupcake','brownie','coffee','baklava'],true)){flash('Review product fields before saving.','error');redirect('admin',['tab'=>'products']);}$args=[$cat,$name,$desc,$details,$price,$stock,$image,$featured];if($id>0){$args[]=$id;$st=db()->prepare('UPDATE products SET category_id=?,name=?,short_description=?,description=?,price=?,stock=?,image_key=?,featured=? WHERE id=?');}else{$st=db()->prepare('INSERT INTO products(category_id,name,short_description,description,price,stock,image_key,featured) VALUES(?,?,?,?,?,?,?,?)');}$st->execute($args);flash('Product saved.');redirect('admin',['tab'=>'products']);}if($action==='admin_product_delete'){$id=(int)($_POST['id']??0);$st=db()->prepare('UPDATE products SET active=0 WHERE id=?');$st->execute([$id]);flash('Product removed from the store.');redirect('admin',['tab'=>'products']);}if($action==='admin_order_status'){$id=(int)($_POST['id']??0);$status=input('status',30);if(!in_array($status,['pending','preparing','ready','completed','cancelled'],true)){http_response_code(422);exit('Invalid status.');}$st=db()->prepare('UPDATE orders SET status=? WHERE id=?');$st->execute([$status,$id]);flash('Order status updated.');redirect('admin',['tab'=>'orders']);}}
http_response_code(400);exit('Unknown action.');
